architecture.h4_f:
tin nhắn = CBOR{v:1, văn bản, trả lời_đến, đã gửi_at}
ct = AES-GCM-256-Encrypt(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, văn bản, reply_to?, thread_id?, đề cập?, đã gửi_at}
ct = AES-GCM-256-Encrypt(room_key, nonce, pt, aad=hex(room_id))
dây = CBOR{
  v: 1,
  bản mã: hex(ct), // độ dài thay đổi
  nonce: hex(12 B),
  sender_pseudo: hex(16 B),
  đã gửi_at: unix_ms
}

cryptoWire.h5_f:
bên ngoài = CBOR{
  source_node: hex32,
  target_user: int64,
  văn bản bên trong: byte,
  bên trong_nonce: byte,
  đã gửi_at: unix_ms
}
sig = Ed25519-Sign(source_priv, bên ngoài)
POST /federation/deliver { phong bì: bên ngoài, sig: hex64 }

auth.h1_f:
POST /api/xác thực/đăng ký
  { tên người dùng, mật khẩu, x25519_public_key, display_name, điện thoại?, email?, avatar_emoji }

Phản hồi 201 Đã tạo:
  { access_token, Refresh_token, user_id, tên người dùng, ... }

auth.h3_f:
tải trọng access_token:
  { sub: user_id, jti: device_id, typ: "access", exp: now + 15 phút }
tải trọng Refresh_token:
  { sub: user_id, jti: device_id, typ: "refresh", exp: now + 30d }

HS256-được ký với bí mật 64 byte của nút từ .env

auth.h4_f:
register_begin(): challenge = rand(32)
                    tùy chọn = { rp.id, user.id, pubKeyCredParams, challenge }
                    tùy chọn trả lại

register_finish(chứng thực):
  xác minh chứng thực đối với TPM / Root Enclave an toàn CA
  lưu trữ { credential_id, public_key, bộ đếm: 0 }

auth.h7_f:
POST /api/xác thực/qr/bắt đầu
  → { nonce: hex 128 bit, ttl: 60 }
QR tải trọng = { nonce, user_id, máy chủ: "https://node.example" }

POST /api/xác thực/qr/xác minh { nonce }
  → thiết bị mới được đăng ký; JWT đã quay trở lại.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 hex
bản mã = AES-GCM-Encrypt(room_key, nonce, CBOR_payload, aad=room_id)

Khung phân tán: { type:"m", room, msg:{id, ct, nonce, sender_pseudo, send_at} }

files.h2_f:
init POST /api/files/resumable/init {tên tệp, kích thước, chunk_size_hint}
            ← {upload_id, chunk_size}
chunk PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct byte>
            ← 204
hoàn thiện POST /api/files/resumable/{upload_id}/finalize {plain_blake3}
            ← 201 {file_id, url}
TTL chưa hoàn thành: 24 h

files.h4_f:
từ chối_list = {
  "ứng dụng/x-dosexec",
  "ứng dụng/x-sharedlib",
  "ứng dụng/x-mach-nhị phân",
}
nếu magic.from_buffer(buf[:1024]) trong den_list: trả về 415

presence.h1_f:
khách hàng: trong lần nhấn phím đầu tiên → gửi {type:"t", state:"start"}
         không gửi nữa trong 3 giây trừ khi trạng thái thay đổi
         10 giây sau lần nhấn phím cuối cùng → gửi {type:"t", state:"stop"}
máy thu: tự động dừng 10 giây sau lần "bắt đầu" cuối cùng nếu không có "dừng" nào đến

calls.h1_f:
POST /api/calls/{room_id}/bắt đầu {video, âm thanh} → call_id
WS phát sóng {loại:"c", loại:"invite", call_id}
WS phát sóng {loại:"c", loại:"ưu đãi", sdp}
WS phát sóng {type:"c", kind:"answer", sdp}
WS phát sóng {loại:"c", loại:"ứng cử viên",ice} × N
POST /api/calls/{call_id}/end

federation.h2_f:
phong bì = {
  source_node : hex32,
  target_user : int64,
  văn bản bên trong: byte,
  bên trong_nonce : byte,
  đã gửi_at : unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(phong bì))
POST /federation/deliver { phong bì, chữ ký }

gossip.h3_f:
quảng cáo = {pubkey, điểm cuối, quảng cáo_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(quảng cáo))
tải trọng tin đồn: [..., {ad, sig}, ...]

người nhận: xác minh sig với ad.pubkey → lưu trữ iff ok
bổ sung: PoW gồm 2^18 số 0 đứng đầu trên {pubkey, endpoint}

stealth.h2_f:
ClientHello byte = chrome_120_template với {
  ngẫu nhiên = ngẫu nhiên của chúng tôi,
  server_name = tên máy chủ của chúng tôi (hoặc được gói ECH),
  session_id = id phiên của chúng tôi,
}
JA4 = t13d_xxxx_xxxx_xxxx (phù hợp với phiên bản Chrome ổn định hiện tại)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {name: x.vortexx.sol}
ECH: ClientHello.extensions += mã hóa_sni(public_key_from_HTTPS_record)
DGA: miền(t) = base32( SHA256(seed ∥ YYYY-MM-DD) )[:16] + ".example"

push.h4_f:
iOS NSE: didReceive(request) { decrypt(request.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
Web SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
công cụ = sign_tool
đầu vào = cây nguồn, khóa/release.key
bảng kê khai = {
  phiên bản: "0.1.0",
  build_at: unix_ms,
  tập tin: [{path, sha256, size}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(manifest))
đầu ra = INTEGRITY.sig.json = {manifest, signature_by: pub_hex, sig: sig_hex}

bots.h1_f:
tạo: POST /api/bots {tên người dùng, display_name, code}
          → {bot_id, mã thông báo, pubkey}
chạy: đang xử lý (coroutine bên trong nút)
      OR bên ngoài (thăm dò ý kiến dài /api/bots/{id}/updates, token-auth'd)
tin nhắn: {văn bản, chữ ký: Ed25519-Sign(bot_priv, canonical_msg)}

bots.h2_f:
bật/bắt đầu {
  phát ra "Chào mừng, {ctx.first_name}"
}
trên /thêm <item> {
  state.list = (state.list hoặc []) + [ctx.args.item]
  phát ra "Đã thêm: {ctx.args.item}"
}

security.h4_f:
canary.txt (hàng ngày):
  {ngày, sig: Ed25519-Sign(release_priv, date)}
khách hàng xác minh → vắng mặt hoặc không hợp lệ ⇒ nghi ngờ có sự thỏa hiệp

khẩn cấp:
  quản trị viên POST /api/admin/revoke-all {lý do}
  nút phát sóng {loại:"n", sự kiện:"thỏa hiệp", lý do}
  khách hàng xóa khóa, buộc khởi động lại

debugging.h2_f:
biểu đồ tốc độ (trên mỗi tuyến + phương thức):
