đồng hồ đo websocket:
  xoáy_ws_connections{node}
  vortex_ws_fanout_queue_deep{phòng,người dùng}

quầy tùy chỉnh:
  xoáy_messages_sent_total{room_type}
  xoáy_calls_started_total{kind}

