fts5.h1_f:
CREATE VIRTUAL TABLE tin nhắn_fts USING fts5(
  nội dung, -- cột được mã hóa
  phòng_id UNINDEXED,
  tokenize = 'unicode61 Remove_diacritics 2'
);
truy vấn: SELECT rowid FROM messages_fts WHERE nội dung MATCH 'foo'

